import{_ as o,o as a,c as t,a2 as d}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Dicionário de Termos","description":"","frontmatter":{},"headers":[],"relativePath":"pt/0090-术语词典.md","filePath":"pt/0090-术语词典.md"}'),i={name:"pt/0090-术语词典.md"};function r(s,e,n,c,m,l){return a(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="dicionario-de-termos" tabindex="-1">Dicionário de Termos <a class="header-anchor" href="#dicionario-de-termos" aria-label="Permalink to &quot;Dicionário de Termos&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do documento</td><td>90</td></tr><tr><td>Módulo</td><td>Apêndices e Materiais de Referência</td></tr><tr><td>Palavras-chave centrais</td><td>dicionário de termos, conceitos centrais, definições, terminologia unificada, Hengyuanzhou</td></tr></tbody></table><h2 id="_1-explicacao-dos-termos" tabindex="-1">1. Explicação dos Termos <a class="header-anchor" href="#_1-explicacao-dos-termos" aria-label="Permalink to &quot;1. Explicação dos Termos&quot;">​</a></h2><p>Este dicionário reúne os termos centrais do sistema de configuração da Civilização de Simbiose de Âncora, com o objetivo de unificar o uso de terminologia em todos os documentos e garantir a consistência e precisão da expressão conceitual. Todos os termos são ordenados pela primeira letra do pinyin chinês, e cada termo inclui o nome do termo, o nome de referência em inglês (se houver), a definição e uma breve explicação. Este dicionário é um documento de atualização dinâmica, e novos termos serão continuamente adicionados à medida que o sistema de configuração se expandir.</p><h2 id="_2-tabela-de-termos-centrais" tabindex="-1">2. Tabela de Termos Centrais <a class="header-anchor" href="#_2-tabela-de-termos-centrais" aria-label="Permalink to &quot;2. Tabela de Termos Centrais&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nº</th><th>Termo</th><th>Definição e Explicação</th></tr></thead><tbody><tr><td>1</td><td>Âncora</td><td>Nó estável na rede de leis, é a referência de coordenadas para manter a estabilidade das leis dimensionais, realizar conexões interdimensionais e retrocesso no tempo. A âncora é essencialmente um condensado de alta densidade das leis fundamentais do universo em uma posição espacial específica, com capacidade de automanutenção e calibração.</td></tr><tr><td>2</td><td>Civilização de Simbiose de Âncora</td><td>Forma de civilização que tem o mecanismo de âncora como base técnica e a evolução por simbiose como conceito central. Opõe-se ao sistema de cultivo predatório, defende devolver o direito de escolha do destino e da evolução a todos os seres, realizando mais trabalho mais ganho, autogerado e autocrescido, todos têm caminho, todas as raças progridem juntas.</td></tr><tr><td>3</td><td>Hengyuanzhou</td><td>Abreviação de &quot;Wanling Hengmao Benyuan Zhou&quot;, é todo o universo habitado e governado pela Civilização de Simbiose de Âncora. É um ser composto por quatro camadas: dimensão material, camada de energia, domínio da consciência e rede de leis.</td></tr><tr><td>4</td><td>Wanling Hengmao Benyuan Zhou</td><td>Nome completo de Hengyuanzhou. &quot;Wanling&quot; refere-se a todas as formas de vida com potencial de percepção e evolução, &quot;Hengmao&quot; refere-se ao mecanismo de âncora que mantém o equilíbrio cósmico, &quot;Benyuan Zhou&quot; enfatiza o atributo essencial de ter as leis fundamentais como base e a evolução por simbiose como direção.</td></tr><tr><td>5</td><td>Simbiose</td><td>Um dos conceitos centrais da Civilização de Simbiose de Âncora, refere-se à evolução conjunta realizada por meio de cooperação mutuamente benéfica entre diferentes indivíduos vivos, raças e civilizações, em vez de evolução predatória às custas dos outros.</td></tr><tr><td>6</td><td>Sistema de Cultivo Predatório</td><td>Método de cultivo que realiza a própria evolução devorando a energia, a sorte e até a origem dos fracos. Tipo de sistema firmemente oposto pela Civilização de Simbiose de Âncora, considerado a raiz do aumento acelerado da entropia cósmica e das frequentes rupturas civilizacionais.</td></tr><tr><td>7</td><td>Trezentos Conjuntos de Sistema de Cultivo de Origem</td><td>Caminhos de cultivo ortodoxos extraídos diretamente das leis fundamentais do universo e verificados por âncoras, totalizando trezentos conjuntos, divididos em seis categorias: dedução de origem, ciclo de vida,法理 espacial, elevação da consciência, rede de simbiose e engenharia aplicada, cinquenta conjuntos por categoria.</td></tr><tr><td>8</td><td>Três Bases de Origem</td><td>Os três primeiros conjuntos de sistema básico entre os trezentos conjuntos — Sistema de Dedução Iterativa (1º conjunto), Sistema de Ciclo de Vida (2º conjunto), Sistema de Controle de法理 Espacial (3º conjunto), que são a base de cultivo de todos os outros sistemas.</td></tr><tr><td>9</td><td>Sistema de Dedução Iterativa</td><td>O 1º conjunto de sistema de cultivo de origem, com a característica central de aumento de dedução de cultivo de cem vezes, usando a aplicação técnica da Fruta de Multiplicação para aumentar a capacidade de dedução em cem vezes, enfatizando a otimização do caminho de cultivo por meio de dedução, verificação e iteração.</td></tr><tr><td>10</td><td>Sistema de Ciclo de Vida</td><td>O 2º conjunto de sistema de cultivo de origem, com o ciclo benigno da energia vital como núcleo, enfatizando que a troca de energia entre o próprio cultivador e o ambiente deve ser cíclica em vez de predatória.</td></tr><tr><td>11</td><td>Sistema de Controle de法理 Espacial</td><td>O 3º conjunto de sistema de cultivo de origem, com a compreensão e controle das leis espaciais como núcleo, é a base de cultivo para aplicações importantes como interação interdimensional, construção de espaço isolado e tecnologia de espelho de cópia.</td></tr><tr><td>12</td><td>Fruta de Multiplicação</td><td>A Fruta de Multiplicação originária do mundo de One Piece, aplicada tecnicamente em Hengyuanzhou, capaz de aumentar a capacidade de dedução do cultivador em cem vezes, é a ferramenta auxiliar central do Sistema de Dedução Iterativa. Um dos buffs iniciais.</td></tr><tr><td>13</td><td>Mecanismo de Contrato de Produção Conjunta</td><td>Mecanismo de alocação de recursos da Civilização de Simbiose de Âncora, que aloca os recursos de cultivo cósmico a indivíduos ou grupos por meio de &quot;contrato&quot;, e os contratantes obtêm o direito de uso dos recursos por meio de trabalho e contribuição, realizando mais trabalho mais ganho.</td></tr><tr><td>14</td><td>Estratégia de Ativação de 20%</td><td>Objetivo estratégico faseado da Civilização de Simbiose de Âncora, ativando 20% de todos os seres do universo na fase inicial para se tornarem os mais fortes supremos dimensionais, usando-os como espinha dorsal para impulsionar a evolução conjunta dos 80% restantes.</td></tr><tr><td>15</td><td>Mais Forte Supremo Dimensional</td><td>Forte que atingiu um reino de cultivo extremamente alto e é capaz de manter sozinho a estabilidade das leis de uma dimensão. É o objeto de cultivo alvo da Estratégia de Ativação de 20% e também uma importante força de manutenção da rede de âncoras.</td></tr><tr><td>16</td><td>Rede de Leis</td><td>A quarta camada da estrutura de Hengyuanzhou, é a camada subjacente de operação das leis fundamentais do universo e a camada raiz das âncoras. A rede de leis percorre todo o universo e é a base técnica de todas as operações legais (incluindo controle espacial, retrocesso no tempo e conversão de energia).</td></tr><tr><td>17</td><td>Dimensão</td><td>Região de existência definida por um conjunto de leis relativamente estáveis, com continuidade espaço-temporal independente. Cada dimensão possui constantes físicas únicas, densidade de energia, velocidade de fluxo temporal e atividade de consciência.</td></tr><tr><td>18</td><td>Barreira de Leis</td><td>Barreira legal que separa dimensões adjacentes, cuja intensidade depende do grau de diferença dos parâmetros legais entre dimensões adjacentes. A travessia dimensional requer superar a barreira de leis.</td></tr><tr><td>19</td><td>Impressão Digital de Leis</td><td>Identificador único gerado por operação de hash dos parâmetros legais centrais de cada dimensão, com comprimento de 128 bits, é um dos parâmetros centrais do sistema de coordenadas dimensionais.</td></tr><tr><td>20</td><td>Primeiro Observar, Depois Interferir Limitadamente</td><td>Princípio operacional primordial do retrocesso no tempo e da arqueologia interdimensional, exigindo que qualquer retrocesso ou arqueologia deva primeiro concluir a fase de observação pura, e somente após confirmar que não há riscos significativos pode-se realizar interferência limitada.</td></tr><tr><td>21</td><td>Espelho de Cópia</td><td>Dispositivo de cópia de alta precisão baseado nas leis espaciais, capaz de realizar cópia completa 1:1 da área alvo sem contato com o objeto original, é o equipamento central do esquema de arqueologia remota.</td></tr><tr><td>22</td><td>Espaço Isolado</td><td>Região legal independente construída por tecnologia de controle de leis espaciais, usada para carregar cópias arqueológicas e como local de trabalho para arqueólogos, completamente separada do universo externo por uma barreira de leis.</td></tr><tr><td>23</td><td>Apenas Retornar Conhecimento</td><td>Princípio central do protocolo arqueológico, refere-se a que o que é obtido do objeto alvo durante a arqueologia só pode ser conhecimento e informação abstratos, e nenhuma matéria, energia ou ser vivo pode ser retornado.</td></tr><tr><td>24</td><td>Purificação de Informação</td><td>Processo técnico de remover completamente a impressão legal da dimensão de origem carregada na informação original, mantendo apenas o conteúdo semântico puro, é um elo chave para garantir a segurança do conhecimento retornado.</td></tr><tr><td>25</td><td>Paradoxo Temporal</td><td>Fenômeno de autocontradição na lógica causal causada por comportamento de interferência durante operações de retrocesso no tempo, incluindo quatro categorias: paradoxo do avô, paradoxo da informação, paradoxo ontológico e paradoxo do evento.</td></tr><tr><td>26</td><td>Cadeia Causal</td><td>Estrutura linear contínua de causa e efeito entre eventos, é o conceito central das leis temporais. O risco central das operações de retrocesso no tempo é a perturbação da cadeia causal.</td></tr><tr><td>27</td><td>Constituição de Simbiose</td><td>Lei fundamental da Civilização de Simbiose de Âncora, com a mais alta eficácia legal, estabelecendo a base civilizacional anti-predatória e pró-simbiose e os sete princípios fundamentais da constituição.</td></tr><tr><td>28</td><td>Igualdade de Todas as Raças</td><td>Um dos sete princípios fundamentais da Constituição de Simbiose, refere-se a que todas as formas de vida, independentemente de raça, nível de cultivo ou origem, são iguais perante a lei.</td></tr><tr><td>29</td><td>Vida Estranha</td><td>Forma de vida que não se encaixa na definição convencional de vida e possui forma de existência especial, requer identificação e gerenciamento de acordo com três tipos de processos de tratamento padronizados.</td></tr><tr><td>30</td><td>Energia Estranha</td><td>Forma de energia que não se encaixa na classificação convencional de energia e possui atributos e padrões de comportamento especiais, requer classificação e controle de acordo com três tipos de processos de tratamento padronizados.</td></tr><tr><td>31</td><td>Substituto das Trevas</td><td>Uma forma especial de vida, envolvendo questões éticas de coexistência de duas almas, requer gerenciamento de acordo com as diretrizes éticas de duas almas e quatro tipos de regras de tratamento de ramificação.</td></tr><tr><td>32</td><td>Ética de Duas Almas</td><td>Diretrizes éticas para o estado de coexistência de duas almas no Substituto das Trevas, o núcleo é respeitar os direitos respectivos das duas almas, proibindo a fusão forçada ou a eliminação de qualquer uma das partes.</td></tr><tr><td>33</td><td>Cinco Tipos de Classificação de Civilização de Simbiose</td><td>Cinco tipos de sociedade simbiótica divididos com base nas características das civilizações do mundo real: tipo intensivo da Ásia Oriental, tipo de bem-estar nórdico, tipo plural da América do Norte, tipo social da Europa continental, tipo de desenvolvimento em追赶.</td></tr><tr><td>34</td><td>Caminho de Elevação de Quatro Fases</td><td>Rota de quatro fases para a elevação geral do universo Hengyuanzhou: base na realidade → capacitação tecnológica → evolução da consciência → simbiose interestelar.</td></tr><tr><td>35</td><td>Realidade como Base</td><td>Uma das posições fundamentais da Civilização de Simbiose de Âncora, refere-se a que o mundo real é o único mundo real, o mundo do romance é um experimento de pensamento falso, o fictício insuficiente é complementado pela realidade, e o que não existe na realidade é criado por atualização baseada em leis.</td></tr><tr><td>36</td><td>Grau de Simbiose</td><td>Indicador quantitativo para avaliar o grau de integração de uma civilização ou indivíduo com a rede de simbiose, abrangendo múltiplas dimensões como grau de compartilhamento de recursos, frequência de cooperação e proporção de comportamento altruísta.</td></tr><tr><td>37</td><td>Conselho de Âncora</td><td>Órgão de poder supremo da Civilização de Simbiose de Âncora, composto por representantes de todas as raças proporcionalmente, exercendo poder legislativo e poder de decisão sobre assuntos importantes.</td></tr><tr><td>38</td><td>Comitê Executivo de Simbiose</td><td>Órgão administrativo supremo da Civilização de Simbiose de Âncora, responsável pela execução da constituição e das leis e pela governança diária.</td></tr><tr><td>39</td><td>Tribunal de Simbiose</td><td>Órgão judicial supremo da Civilização de Simbiose de Âncora, exercendo independentemente o poder de julgamento, responsável pela revisão de inconstitucionalidade e pelo julgamento de casos importantes.</td></tr><tr><td>40</td><td>Agência de Gerenciamento Dimensional</td><td>Órgão especial subordinado ao Conselho de Âncora, responsável pela manutenção do banco total de coordenadas dimensionais, aprovação de licenças de travessia, gerenciamento de arqueologia interdimensional e outros assuntos.</td></tr></tbody></table><h2 id="_3-normas-de-uso-de-termos" tabindex="-1">3. Normas de Uso de Termos <a class="header-anchor" href="#_3-normas-de-uso-de-termos" aria-label="Permalink to &quot;3. Normas de Uso de Termos&quot;">​</a></h2><ol><li>Os termos coletados neste dicionário são termos padrão, e todos os documentos devem priorizar o uso das expressões padrão neste dicionário.</li><li>O mesmo conceito deve usar o mesmo termo em diferentes documentos, e não se pode trocar sinônimos à vontade.</li><li>Novos termos gerados em novas configurações devem ser prontamente submetidos ao comitê de terminologia para revisão, e após a aprovação na revisão, serão adicionados a este dicionário.</li><li>Se a definição de um termo for revisada, a versão mais recente deste dicionário prevalece, e ao mesmo tempo o conteúdo da revisão deve ser registrado na explicação da versão do documento.</li><li>Ao citar um termo, o nome completo pode ser usado na primeira ocorrência, e a abreviação pode ser usada subsequentemente, mas deve-se garantir que o significado no contexto seja claro.</li></ol><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>O dicionário de termos é a pedra angular linguística de todo o sistema de configuração. O sistema de terminologia unificado garante a consistência conceitual entre os cem documentos, permitindo que os leitores alternem perfeitamente entre diferentes módulos sem ambiguidade de compreensão. Com o enriquecimento e aprimoramento contínuos do sistema de configuração, este dicionário será continuamente atualizado, servindo sempre como a fonte autoritativa de terminologia para todos os documentos.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>00-Visão Geral do Universo Hengyuanzhou</li><li>02-Definição e Essência da Origem da Âncora</li><li>99-Explicação de Versão e Manutenção de Documentos</li></ul>',12)])])}const v=o(i,[["render",r]]);export{p as __pageData,v as default};
